async function foldArchive(chunks, initial, reduce) {
  const decoder = new TextDecoder("utf-8");
  const iterator = chunks[Symbol.asyncIterator]();

  let state = initial;
  let physicalLine = 0;
  let recordIndex = 0;
  let currentLine = "";
  let sourceEnded = false;
  let cleanupStarted = false;

  const cleanup = async () => {
    if (cleanupStarted || sourceEnded) return;
    cleanupStarted = true;

    let returnMethod;
    try {
      returnMethod = iterator.return;
    } catch {
      return;
    }

    if (typeof returnMethod !== "function") return;

    try {
      await returnMethod.call(iterator);
    } catch {
      // Cleanup failures are ignored.
    }
  };

  const processLine = async (line) => {
    const lineNumber = ++physicalLine;

    if (line.trim() === "") return false;

    let value;
    try {
      value = JSON.parse(line);
    } catch {
      return false;
    }

    const result = await reduce(state, value, {
      physicalLine: lineNumber,
      recordIndex
    });

    state = result.state;
    recordIndex += 1;

    return result.done === true;
  };

  const processText = async (text) => {
    let start = 0;

    for (let i = 0; i < text.length; i += 1) {
      if (text.charCodeAt(i) !== 10) continue;

      currentLine += text.slice(start, i);
      start = i + 1;

      if (currentLine.endsWith("\r")) {
        currentLine = currentLine.slice(0, -1);
      }

      const stopped = await processLine(currentLine);
      currentLine = "";

      if (stopped) return true;
    }

    currentLine += text.slice(start);
    return false;
  };

  try {
    while (true) {
      const step = await iterator.next();

      if (step.done) {
        sourceEnded = true;

        if (await processText(decoder.decode())) {
          return state;
        }

        if (currentLine.length > 0) {
          const stopped = await processLine(currentLine);
          currentLine = "";

          if (stopped) return state;
        }

        return state;
      }

      const text = decoder.decode(step.value, { stream: true });

      if (await processText(text)) {
        await cleanup();
        return state;
      }
    }
  } catch (error) {
    await cleanup();
    throw error;
  }
}
